import {mainQuery} from '@github-ui/react-core/future/main-query'
import {railsPartialQuery} from '@github-ui/react-core/future/rails-partial-query'

import {reactSandboxFutureAppBuilder} from '../config/app-builder'
import type {RailsPartialsPayload} from '../types'

export const reactSandboxFutureRailsPartialsRoute = reactSandboxFutureAppBuilder.createQueryRouteConfig(
  'reactSandboxFutureRailsPartialsRoute',
  {
    path: '/_react_sandbox_future/rails_partials',
    queries: [
      mainQuery<RailsPartialsPayload>(),
      railsPartialQuery({
        partialName: 'LeftContent',
        queryDeps: ({pathname}) => {
          return {pathname: `${pathname}/left_content`}
        },
      }),
      railsPartialQuery({
        partialName: 'RightContent',
        queryDeps: ({pathname}) => {
          return {pathname: `${pathname}/right_content`}
        },
      }),
      railsPartialQuery({
        partialName: 'HeadContent',
        queryDeps: ({pathname}) => {
          return {pathname: `${pathname}/head_content`}
        },
      }),
    ],
  },
)
